import {useMemo, useState} from 'react';
import ChartKit from '@gravity-ui/chartkit';
import {Button, Loader, SegmentedRadioGroup, Text} from '@gravity-ui/uikit';
import {salesConfig, monitoringConfig} from '../lib/chart-config';
import {summarize, toCsv} from '../lib/data';
import type {VisualizationWidgetProps, WidgetMode} from '../lib/types';
import '../lib/chartkit';

const number = (value: number) => new Intl.NumberFormat('ru-RU', {maximumFractionDigits: 0}).format(value);
const date = (value: number) => new Intl.DateTimeFormat('ru-RU', {day: 'numeric', month: 'short', timeZone: 'UTC'}).format(value);

function ChartState({kind, message, retry}: {kind: 'loading' | 'empty' | 'error'; message?: string; retry?: () => void}) {
  return <div className=\"chart-state\" role={kind === 'error' ? 'alert' : 'status'}>{kind === 'loading' ? <Loader size=\"m\"/> : <span className=\"state-symbol\">{kind === 'empty' ? '∅' : '"'!'"'}</span>}<Text variant=\"subheader-2\">{message ?? (kind === 'loading' ? 'Загружаем график…' : 'Нет данных за этот период')}</Text>{retry && <Button onClick={retry}>Повторить</Button>}</div>;
}

export function VisualizationWidget({mode, onModeChange, data, range, onRangeChange, updatedAt, onRefresh, loading, error}: VisualizationWidgetProps) {
  const [hidden, setHidden] = useState<string[]>([]);
  const [retry, setRetry] = useState(0);
  const [exported, setExported] = useState(false);
  const stats = useMemo(() => summarize(data), [data]);
  const sales = mode === 'sales';
  const rangeOptions = sales ? [{value: '7', content: '7 дней'}, {value: '30', content: '30 дней'}, {value: '90', content: '90 дней'}] : [{value: '1', content: '1 час'}, {value: '6', content: '6 часов'}, {value: '24', content: '24 часа'}];
  const chartData = useMemo(() => sales ? salesConfig(data, hidden) : monitoringConfig(data, hidden), [sales, data, hidden]);
  const empty = "'!data.timeline.length || !data.series.some((s) => !hidden.includes(s.id) && s.values.some((v) => v !== null));
  const toggleSeries = (id: string) => setHidden((current) => current.includes(id) ? current.filter((x) => x !== id) : [...current, id]);
  const exportCsv = () => {
    const url = URL.createObjectURL(new Blob([toCsv(data)], {type: '"'text/csv;charset=utf-8;'}));
    const link = document.createElement('a'); link.href = url; link.download = "'`pulse-${mode}-${range}.csv`; link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    setExported(true); setTimeout(() => setExported(false), 2500);
  };

  return <section className="visualization-widget" aria-label="Виджет визуализации">
